import { RadarChart, type RadarChartSeriesToggleDetail } from '@absoluteui/components/radar-chart';

const host = document.createElement('div');
document.body.append(host);
const chart = RadarChart.create(host, {
  label: 'Candidate skills',
  axes: ['Design', 'Frontend', 'Backend', 'Testing', 'Operations'],
  series: [
    { id: 'ana', label: 'Ana', values: [4, 5, 3, 4, 2] },
    { id: 'ben', label: 'Ben', values: [2, 3, 5, 3, 4] },
  ],
  valueAxis: { min: 0, max: 5, tickCount: 5 },
});
host.addEventListener('aui-series-toggle', (event) => {
  const { hidden } = (event as CustomEvent<RadarChartSeriesToggleDetail>).detail;
  host.dataset.hidden = hidden.join(',');
});
chart.setSeriesVisible('ben', false);

import { RadarChart } from '@absoluteui/components/radar-chart';

const host = document.querySelector<HTMLElement>('#coverage');
if (host) {
  RadarChart.create(host, {
    label: 'Test coverage by module',
    axes: ['Auth', 'Billing', 'Search', 'Reports', 'Admin', 'API'],
    series: [
      { id: 'unit', label: 'Unit', values: [0.9, 0.75, 0.6, null, 0.8, 0.95], color: 1 },
      { id: 'e2e', label: 'End-to-end', values: [0.6, 0.5, 0.4, 0.3, 0.2, 0.7], color: 4 },
    ],
    valueAxis: { min: 0, max: 1 },
    valueFormat: { style: 'percent' },
    fill: false,
    dataTable: 'visible',
  });
}
